<?php foreach($entries as $e):?><dialog id="entri-<?=(int)$e['id']?>"><form method="post" action="/entri/<?=(int)$e['id']?>/kemas-kini" class="dialog-form"><?=Csrf::field()?><header><div><p class="eyebrow">Entri <?=(int)$e['entry_no']?></p><h2>Kemas kini entri</h2></div><button type="button" class="icon-button" data-dialog-close>×</button></header><?=entry_fields($e)?><?php if($volume['status']!=='Open'&&$user['role']==='Admin'):?><label class="check"><input type="checkbox" name="correction_mode" value="1" required><span><strong>Aktifkan mod pembetulan Admin</strong><small>Jilid sejarah tidak membenarkan pengarkiban entri.</small></span></label><?php endif?><footer><button type="button" class="button quiet" data-dialog-close>Batal</button><button class="button primary">Simpan perubahan</button></footer></form><?php if($volume['status']==='Open'):?><form method="post" action="/entri/<?=(int)$e['id']?>/arkib" class="archive-strip" data-confirm="Arkibkan entri ini? Nombor surat tidak akan digunakan semula."><?=Csrf::field()?><button class="danger-text">Arkib entri</button></form><?php endif?></dialog><?php endforeach?>
