<?php if($volume['status']==='Open'||$user['role']==='Admin'):?><dialog id="entri-baru"><form method="post" action="/jilid/<?=(int)$volume['id']?>/entri" class="dialog-form"><?=Csrf::field()?><header><div><p class="eyebrow">Jilid <?=(int)$volume['sequence_no']?></p><h2>Tambah entri</h2></div><button type="button" class="icon-button" data-dialog-close>×</button></header><?php if($volume['status']!=='Open'):?><p class="warning-text">Anda sedang menambah entri ke jilid yang telah ditutup. Tindakan ini hanya dibenarkan untuk Admin.</p><?php endif?><?php if($user['role']==='Admin'&&$numbering['editable']):?><label class="check numbering-warning"><input type="checkbox" name="confirm_volume_numbering_fixed" value="1" required><span><strong>Entri pertama akan menetapkan nombor jilid secara kekal</strong><small>Selepas entri ini disimpan, nombor semua jilid dalam fail ini tidak boleh dinaikkan atau diturunkan lagi.</small></span></label><?php endif?><?=entry_fields([])?><footer><button type="button" class="button quiet" data-dialog-close>Batal</button><button class="button primary">Simpan entri</button></footer></form></dialog><?php endif?>
<?php if($user['role']==='Admin'):?><?php if((int)$volume['total_entry_count']===0):?><dialog id="import-csv"><form method="post" action="/jilid/<?=(int)$volume['id']?>/import" enctype="multipart/form-data" class="dialog-form"><?=Csrf::field()?><h2>Import CSV</h2><p>Admin sahaja. Jilid mesti belum pernah mempunyai sebarang entri. Maksimum 10,000 baris atau 5 MB.</p><label>Fail CSV<input type="file" name="csv" accept=".csv,text/csv" required><small>Pengepala Melayu atau Inggeris diterima.</small></label><footer><button type="button" class="button quiet" data-dialog-close>Batal</button><button class="button primary">Semak fail</button></footer></form></dialog><?php endif?><dialog id="jilid-baru"><form method="post" action="/fail/<?=(int)$folder['id']?>/jilid" class="dialog-form"><?=Csrf::field()?><h2>Buka Jilid <?=(int)$volumes[0]['sequence_no']+1?></h2><p>Jilid semasa akan ditutup untuk penambahan biasa. Admin masih boleh menambah entri jika diperlukan.</p><label>Tarikh mula liputan <span>(pilihan)</span><input type="date" name="coverage_start"></label><label>Keterangan <span>(pilihan)</span><textarea name="description" maxlength="500"></textarea></label><footer><button type="button" class="button quiet" data-dialog-close>Batal</button><button class="button primary">Tutup & teruskan</button></footer></form></dialog><dialog id="arkib-fail"><form method="post" action="/arkib/fail/<?=(int)$folder['id']?>" class="dialog-form"><?=Csrf::field()?><h2>Arkib seluruh fail?</h2><p>Semua jilid dan entri akan diarkibkan. Tiada pemulihan melalui aplikasi.</p><footer><button type="button" class="button quiet" data-dialog-close>Batal</button><button class="button danger">Arkib fail</button></footer></form></dialog><?php endif?>
<?php function entry_fields(array $e):string{ob_start();?><div class="form-grid"><label>Jenis<select name="type" required><option value="Incoming" <?=($e['type']??'')==='Incoming'?'selected':''?>>Masuk</option><option value="Outgoing" <?=($e['type']??'')==='Outgoing'?'selected':''?>>Keluar</option></select></label><label>Surat Bertarikh<input type="date" name="letter_date" value="<?=View::e($e['letter_date']??'')?>" required></label></div><label>Daripada/Kepada<input name="correspondent" maxlength="150" value="<?=View::e($e['correspondent']??'')?>" required></label><label>Dimasukkan/Dihantar<input type="date" name="movement_date" value="<?=View::e($e['movement_date']??'')?>" required></label><label>Perkara<textarea name="matter" maxlength="500" rows="3" required><?=View::e($e['matter']??'')?></textarea></label><label>Catatan <span>(pilihan)</span><textarea name="remarks" maxlength="500" rows="2"><?=View::e($e['remarks']??'')?></textarea></label><label class="check"><input type="checkbox" name="confirm_chronology" value="1"><span><strong>Sahkan jika kronologi tarikh terbalik</strong><small>Diperlukan hanya jika tarikh dimasukkan/dihantar lebih awal daripada surat.</small></span></label><?php return(string)ob_get_clean();}?>
